//! Known-answer tests against vectors produced by Ente's own client code.
//!
//! * `vectors/ente_core_vectors.json`: from `node/tests/crypto_vectors/`
//!   (branch `claude/project-thread-bmpbpi`), generated by running Ente's
//!   `ente-accounts` / `ente-core` Rust crates (ente-io/ente commit
//!   b2ed3dc93e49d6ac9831bf3550957816d3a0735d). The tests are adapted from
//!   `node/tests/crypto_ente_vectors.rs`.
//! * `vectors/{keys,srp,sealed_token,libsodium}.json`: copies of
//!   `server/tests/vectors/` (same upstream commit; see the README there),
//!   which the contract names as the reference for SRP and key derivation.

use num_bigint_dig::BigUint;
use photovault_core::crypto::{self, StreamDecryptor, StreamEncryptor};
use photovault_core::srp::{self, SrpClient};
use serde_json::Value;
use sha2::{Digest, Sha256};

fn vectors() -> Value {
    serde_json::from_str(include_str!("vectors/ente_core_vectors.json")).unwrap()
}

fn server_vectors(name: &str) -> Value {
    let s = match name {
        "keys" => include_str!("vectors/keys.json"),
        "srp" => include_str!("vectors/srp.json"),
        "sealed_token" => include_str!("vectors/sealed_token.json"),
        "libsodium" => include_str!("vectors/libsodium.json"),
        _ => unreachable!(),
    };
    serde_json::from_str(s).unwrap()
}

fn hx(v: &Value) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}

fn b64(v: &Value) -> Vec<u8> {
    crypto::unb64(v.as_str().unwrap()).unwrap()
}

/// Deterministic plaintext used by the node generator.
fn pattern(n: usize) -> Vec<u8> {
    (0..n).map(|i| ((i * 31 + 7) % 251) as u8).collect()
}

/// Encrypt with Ente's chunking and a fixed header.
fn encrypt_with_header(data: &[u8], header: &[u8], key: &[u8]) -> Vec<u8> {
    let mut enc = StreamEncryptor::with_header(key, header).unwrap();
    let c = crypto::ENCRYPTION_CHUNK_SIZE;
    if data.is_empty() {
        return enc.push(&[], true).unwrap();
    }
    let n = data.len().div_ceil(c);
    let mut out = Vec::new();
    for (i, chunk) in data.chunks(c).enumerate() {
        out.extend(enc.push(chunk, i + 1 == n).unwrap());
    }
    out
}

#[test]
fn argon2id_matches_ente() {
    for v in vectors()["argon2id"].as_array().unwrap() {
        let k = crypto::derive_argon_key(
            v["password"].as_str().unwrap().as_bytes(),
            &b64(&v["salt_b64"]),
            v["ops_limit"].as_u64().unwrap(),
            v["mem_limit"].as_u64().unwrap(),
        )
        .unwrap();
        assert_eq!(hex::encode(k), v["key_hex"].as_str().unwrap(), "{v}");
    }
}

#[test]
fn kdf_login_subkey_matches_ente() {
    let v = &vectors()["kdf"];
    let k = hx(&v["key_hex"]);
    assert_eq!(
        crypto::derive_login_key(&k).unwrap(),
        hx(&v["login_subkey_hex"])
    );
    assert_eq!(
        crypto::derive_subkey(&k, 32, 1, b"loginctx").unwrap(),
        hx(&v["subkey_32_1_loginctx_hex"])
    );
    assert_eq!(
        crypto::derive_subkey(&k, 64, 7, b"context0").unwrap(),
        hx(&v["subkey_64_7_context0_hex"])
    );
}

#[test]
fn secretbox_matches_ente() {
    let v = &vectors()["secretbox"];
    let k = hx(&v["key_hex"]);
    let (nonce, ct, pt) = (
        b64(&v["nonce_b64"]),
        b64(&v["ciphertext_b64"]),
        hx(&v["plaintext_hex"]),
    );
    assert_eq!(crypto::secretbox_open(&ct, &nonce, &k).unwrap(), pt);
    assert_eq!(
        crypto::secretbox_seal_with_nonce(&pt, &nonce, &k).unwrap(),
        ct
    );
}

#[test]
fn sealed_box_matches_ente() {
    let v = &vectors()["sealed_box"];
    let sk = hx(&v["secret_key_hex"]);
    let pk = crypto::public_key_from_secret(&sk).unwrap();
    assert_eq!(pk, hx(&v["public_key_hex"]));
    let pt = crypto::box_seal_open(&b64(&v["ciphertext_b64"]), &pk, &sk).unwrap();
    assert_eq!(pt, hx(&v["plaintext_hex"]));
    let ours = crypto::box_seal(&pt, &pk).unwrap();
    assert_eq!(crypto::box_seal_open(&ours, &pk, &sk).unwrap(), pt);
}

#[test]
fn blob_matches_ente() {
    for v in vectors()["blob"].as_array().unwrap() {
        let k = hx(&v["key_hex"]);
        let (header, ct, pt) = (
            b64(&v["header_b64"]),
            b64(&v["ciphertext_b64"]),
            hx(&v["plaintext_hex"]),
        );
        assert_eq!(crypto::decrypt_blob(&ct, &header, &k).unwrap(), pt);
        assert_eq!(
            encrypt_with_header(&pt, &header, &k),
            ct,
            "same key+header gives Ente's bytes"
        );
    }
}

#[test]
fn chunked_file_stream_matches_ente() {
    for v in vectors()["stream_file"].as_array().unwrap() {
        let k = hx(&v["key_hex"]);
        let header = b64(&v["header_b64"]);
        let pt = pattern(v["plaintext_len"].as_u64().unwrap() as usize);
        assert_eq!(
            hex::encode(Sha256::digest(&pt)),
            v["plaintext_sha256"].as_str().unwrap()
        );
        let ours = encrypt_with_header(&pt, &header, &k);
        assert_eq!(ours.len() as u64, v["ciphertext_len"].as_u64().unwrap());
        assert_eq!(
            hex::encode(Sha256::digest(&ours)),
            v["ciphertext_sha256"].as_str().unwrap(),
            "size {}",
            pt.len()
        );
        if let Some(ct) = v["ciphertext_b64"].as_str() {
            assert_eq!(crypto::unb64(ct).unwrap(), ours);
        }
        assert_eq!(crypto::decrypt_stream(&ours, &header, &k).unwrap(), pt);
        // Chunk by chunk, as downloads do.
        let mut dec = StreamDecryptor::new(&k, &header).unwrap();
        let mut got = Vec::new();
        for c in ours.chunks(crypto::DECRYPTION_CHUNK_SIZE) {
            got.extend(dec.pull(c).unwrap().0);
        }
        assert!(dec.is_finished());
        assert_eq!(got, pt);
    }
}

#[test]
fn account_unlock_matches_ente_signup() {
    let a = &vectors()["account"];
    let ka = &a["key_attributes"];
    let kek = crypto::derive_argon_key(
        a["password"].as_str().unwrap().as_bytes(),
        &b64(&ka["kekSalt"]),
        ka["opsLimit"].as_u64().unwrap(),
        ka["memLimit"].as_u64().unwrap(),
    )
    .unwrap();
    assert_eq!(kek, hx(&a["kek_hex"]));
    assert_eq!(
        crypto::derive_login_key(&kek).unwrap(),
        hx(&a["login_key_hex"])
    );
    let master = crypto::secretbox_open(
        &b64(&ka["encryptedKey"]),
        &b64(&ka["keyDecryptionNonce"]),
        &kek,
    )
    .unwrap();
    assert_eq!(master, b64(&a["master_key_b64"]));
    let secret = crypto::secretbox_open(
        &b64(&ka["encryptedSecretKey"]),
        &b64(&ka["secretKeyDecryptionNonce"]),
        &master,
    )
    .unwrap();
    assert_eq!(secret, b64(&a["secret_key_b64"]));
    let pk = b64(&ka["publicKey"]);
    let token = crypto::box_seal_open(&b64(&a["encrypted_token_b64"]), &pk, &secret).unwrap();
    assert_eq!(token, hx(&a["token_hex"]));
    assert_eq!(
        base64::Engine::encode(&base64::engine::general_purpose::URL_SAFE, &token),
        a["token_b64url"].as_str().unwrap()
    );
    // Wrong password: the master key does not open.
    let bad = crypto::derive_argon_key(b"nope", &b64(&ka["kekSalt"]), 2, 67_108_864).unwrap();
    assert!(
        crypto::secretbox_open(
            &b64(&ka["encryptedKey"]),
            &b64(&ka["keyDecryptionNonce"]),
            &bad
        )
        .is_err()
    );
    // The recovery key opens the master key too (and is wrapped by it).
    let rk = crypto::secretbox_open(
        &b64(&ka["recoveryKeyEncryptedWithMasterKey"]),
        &b64(&ka["recoveryKeyDecryptionNonce"]),
        &master,
    )
    .unwrap();
    let m2 = crypto::secretbox_open(
        &b64(&ka["masterKeyEncryptedWithRecoveryKey"]),
        &b64(&ka["masterKeyDecryptionNonce"]),
        &rk,
    )
    .unwrap();
    assert_eq!(m2, master);
    // The SRP verifier Ente registered for this login key.
    let v = srp::verifier(
        a["srp_user_id"].as_str().unwrap().as_bytes(),
        &b64(&a["srp_salt_b64"]),
        &hx(&a["login_key_hex"]),
    );
    assert_eq!(
        BigUint::from_bytes_be(&v),
        BigUint::from_bytes_be(&b64(&a["srp_verifier_b64"]))
    );
}

#[test]
fn library_produced_by_ente_decrypts() {
    let a = &vectors()["account"];
    let lib = &a["library"];
    let master = b64(&a["master_key_b64"]);
    let secret = b64(&a["secret_key_b64"]);
    let public = b64(&a["key_attributes"]["publicKey"]);
    let mut keys = std::collections::HashMap::new();
    for c in lib["collections"].as_array().unwrap() {
        let owned = c["owner"]["id"].as_i64() == Some(1);
        let key = if owned {
            crypto::secretbox_open(
                &b64(&c["encryptedKey"]),
                &b64(&c["keyDecryptionNonce"]),
                &master,
            )
            .unwrap()
        } else {
            crypto::box_seal_open(&b64(&c["encryptedKey"]), &public, &secret).unwrap()
        };
        let name = crypto::secretbox_open(
            &b64(&c["encryptedName"]),
            &b64(&c["nameDecryptionNonce"]),
            &key,
        )
        .unwrap();
        assert!(!name.is_empty());
        keys.insert(c["id"].as_i64().unwrap(), key);
    }
    for (cid, diff) in lib["diffs"].as_object().unwrap() {
        for f in diff.as_array().unwrap() {
            let ck = &keys[&cid.parse::<i64>().unwrap()];
            let fk = crypto::secretbox_open(
                &b64(&f["encryptedKey"]),
                &b64(&f["keyDecryptionNonce"]),
                ck,
            )
            .unwrap();
            let id = f["id"].as_i64().unwrap().to_string();
            assert_eq!(fk, hx(&lib["file_keys_hex"][&id]));
            let md = photovault_core::metadata::decrypt_json(
                f["metadata"]["encryptedData"].as_str().unwrap(),
                f["metadata"]["decryptionHeader"].as_str().unwrap(),
                &fk,
            )
            .unwrap();
            assert_eq!(md, lib["metadata"][&id]);
            if id == "100" {
                let t = crypto::decrypt_blob(
                    &b64(&lib["thumbnail_100_b64"]),
                    &b64(&f["thumbnail"]["decryptionHeader"]),
                    &fk,
                )
                .unwrap();
                assert_eq!(
                    hex::encode(Sha256::digest(&t)),
                    lib["thumbnail_100_plain_sha256"].as_str().unwrap()
                );
                let o = crypto::decrypt_stream(
                    &b64(&lib["original_100_b64"]),
                    &b64(&f["file"]["decryptionHeader"]),
                    &fk,
                )
                .unwrap();
                assert_eq!(
                    hex::encode(Sha256::digest(&o)),
                    lib["original_100_plain_sha256"].as_str().unwrap()
                );
                let pm = photovault_core::metadata::decrypt_magic(
                    &serde_json::from_value(f["pubMagicMetadata"].clone()).unwrap(),
                    &fk,
                )
                .unwrap();
                assert_eq!(
                    pm.data.len() as i64,
                    f["pubMagicMetadata"]["count"].as_i64().unwrap()
                );
            }
        }
    }
}

#[test]
fn srp_client_matches_ente() {
    let s = &vectors()["srp"];
    let (salt, lk) = (hx(&s["salt_hex"]), hx(&s["login_key_hex"]));
    let id = s["identity"].as_str().unwrap();
    assert_eq!(
        srp::verifier(id.as_bytes(), &salt, &lk),
        hx(&s["verifier_hex"])
    );
    let mut c = SrpClient::with_secret(id.as_bytes(), &salt, &lk, &hx(&s["a_private_hex"]));
    assert_eq!(c.public_a(), hx(&s["A_hex"]));
    assert_eq!(c.compute_m1(&hx(&s["B_hex"])).unwrap(), hx(&s["M1_hex"]));
    c.verify_m2(&hx(&s["M2_hex"])).unwrap();
    let mut bad = hx(&s["M2_hex"]);
    bad[0] ^= 1;
    assert!(c.verify_m2(&bad).is_err());
}

/// Ente's `test_known_vector_leading_zero_a_matches_go_server_m1`: M1 from
/// museum's go-srp for an `A` with a leading zero byte.
#[test]
fn srp_m1_matches_go_server_vector() {
    let (id, salt, lk) = ("repro-user-id", b"0123456789abcdef", b"1234567890abcdef");
    let a = hex::decode(format!("{}06de", "0".repeat(124))).unwrap();
    let v = srp::verifier(id.as_bytes(), salt, lk);
    let b = photovault_server::users::srp::server_b(&v, &[0x42u8; 64]);
    let mut c = SrpClient::with_secret(id.as_bytes(), salt, lk, &a);
    assert_eq!(c.public_a()[0], 0, "vector exercises a leading zero in A");
    assert_eq!(
        hex::encode(c.compute_m1(&b).unwrap()),
        "c0953b8c74d400fbf664a515deb700d73b65231e7e207a2e2326ff8cf70567ac"
    );
}

// ---- server/tests/vectors ----

#[test]
fn server_keys_fixture_unlocks_and_recovery_mnemonic_matches() {
    let v = server_vectors("keys");
    let ka = &v["keyAttributes"];
    let p = &v["plaintext"];
    let kek = crypto::derive_argon_key(
        v["password"].as_str().unwrap().as_bytes(),
        &b64(&ka["kekSalt"]),
        ka["opsLimit"].as_u64().unwrap(),
        ka["memLimit"].as_u64().unwrap(),
    )
    .unwrap();
    assert_eq!(kek, b64(&p["kek"]));
    assert_eq!(
        crypto::derive_login_key(&kek).unwrap(),
        b64(&p["loginSubKey"])
    );
    let master = crypto::secretbox_open(
        &b64(&ka["encryptedKey"]),
        &b64(&ka["keyDecryptionNonce"]),
        &kek,
    )
    .unwrap();
    assert_eq!(master, b64(&p["masterKey"]));
    // Recovery key: hex and Ente's 24-word mnemonic both parse to the same key,
    // and that key opens the master key.
    let hex_key = p["recoveryKeyHex"].as_str().unwrap();
    let words = p["recoveryKeyMnemonic"].as_str().unwrap();
    let rk = crypto::parse_recovery_key(hex_key).unwrap();
    assert_eq!(crypto::parse_recovery_key(words).unwrap(), rk);
    assert_eq!(crypto::recovery_key_to_mnemonic(&rk).unwrap(), words);
    let shouty = words.to_uppercase().replace(' ', ",  \n");
    assert_eq!(crypto::parse_recovery_key(&shouty).unwrap(), rk);
    let m = crypto::secretbox_open(
        &b64(&ka["masterKeyEncryptedWithRecoveryKey"]),
        &b64(&ka["masterKeyDecryptionNonce"]),
        &rk,
    )
    .unwrap();
    assert_eq!(m, master);
    // A word swapped breaks the checksum.
    let mut w: Vec<&str> = words.split(' ').collect();
    w.swap(0, 1);
    assert!(crypto::parse_recovery_key(&w.join(" ")).is_err());
    assert!(crypto::parse_recovery_key("abcd").is_err());
}

#[test]
fn server_srp_transcript_matches() {
    let v = server_vectors("srp");
    let setup = &v["setup"];
    let login = &v["login"];
    let lk = b64(&v["derived"]["loginSubKey"]);
    assert_eq!(
        crypto::derive_login_key(&b64(&v["derived"]["kek"])).unwrap(),
        lk
    );
    let id = setup["srpUserID"].as_str().unwrap();
    let salt = b64(&setup["srpSalt"]);
    assert_eq!(
        srp::verifier(id.as_bytes(), &salt, &lk),
        b64(&setup["srpVerifier"])
    );
    let mut c = SrpClient::with_secret(id.as_bytes(), &salt, &lk, &hx(&login["a_hex"]));
    assert_eq!(c.public_a(), b64(&login["srpA"]), "A is sent padded");
    assert_eq!(
        c.compute_m1(&b64(&login["srpB"])).unwrap(),
        b64(&login["srpM1"])
    );
    assert_eq!(
        c.session_key().unwrap(),
        b64(&login["sessionKeyK"]).as_slice()
    );
    c.verify_m2(&b64(&login["srpM2"])).unwrap();

    let g = &v["goServerVector"];
    let (gid, gsalt, glk) = (
        g["srpUserID"].as_str().unwrap(),
        b64(&g["srpSalt"]),
        b64(&g["loginSubKey"]),
    );
    assert_eq!(
        srp::verifier(gid.as_bytes(), &gsalt, &glk),
        b64(&g["srpVerifier"])
    );
    let mut c = SrpClient::with_secret(gid.as_bytes(), &gsalt, &glk, &hx(&g["a_hex"]));
    assert_eq!(c.public_a(), b64(&g["srpA"]));
    assert_eq!(c.compute_m1(&b64(&g["srpB"])).unwrap(), b64(&g["srpM1"]));
    c.verify_m2(&b64(&g["srpM2"])).unwrap();
}

/// 256 MiB × 16 Argon2id, as the web app derives at signup.
#[test]
#[ignore = "slow: 256 MiB x 16 argon2id; run with --ignored"]
fn server_srp_fixture_kek_matches() {
    let v = server_vectors("srp");
    let i = &v["inputs"];
    let kek = crypto::derive_argon_key(
        i["password"].as_str().unwrap().as_bytes(),
        &b64(&i["kekSalt"]),
        i["opsLimit"].as_u64().unwrap(),
        i["memLimit"].as_u64().unwrap(),
    )
    .unwrap();
    assert_eq!(kek, b64(&v["derived"]["kek"]));
}

#[test]
fn server_sealed_token_opens() {
    let v = server_vectors("sealed_token");
    let pt = crypto::box_seal_open(
        &b64(&v["encryptedToken"]),
        &b64(&v["publicKey"]),
        &b64(&v["secretKey"]),
    )
    .unwrap();
    assert_eq!(pt, b64(&v["plaintext"]));
    assert!(pt.starts_with(b"auth-token"));
}

#[test]
fn server_libsodium_fixture_opens() {
    let v = server_vectors("libsodium");
    let sb = &v["secretbox"];
    assert_eq!(
        crypto::secretbox_open(
            &b64(&sb["encryptedData"]),
            &b64(&sb["nonce"]),
            &b64(&sb["key"])
        )
        .unwrap(),
        b64(&sb["plaintext"])
    );
    let fk = &v["fileKey"];
    assert_eq!(
        crypto::secretbox_open(
            &b64(&fk["encryptedKey"]),
            &b64(&fk["keyDecryptionNonce"]),
            &b64(&fk["collectionKey"])
        )
        .unwrap(),
        b64(&fk["fileKey"])
    );
    let md = &v["metadata"];
    let json = photovault_core::metadata::decrypt_json(
        md["encryptedData"].as_str().unwrap(),
        md["decryptionHeader"].as_str().unwrap(),
        &b64(&md["key"]),
    )
    .unwrap();
    let want: Value = serde_json::from_str(md["json"].as_str().unwrap()).unwrap();
    assert_eq!(json, want);
    for k in ["thumbnail", "file"] {
        let o = &v[k];
        let pt = crypto::decrypt_stream(
            &b64(&o["encryptedData"]),
            &b64(&o["decryptionHeader"]),
            &b64(&o["key"]),
        )
        .unwrap();
        assert_eq!(pt, b64(&o["plaintext"]), "{k}");
    }
    let mut h = crypto::Hasher::new();
    h.update(&b64(&v["file"]["plaintext"]));
    assert_eq!(h.finalize(), b64(&v["file"]["blake2b512"]));
    // The fixture's two-chunk stream starts with a 1000-byte MESSAGE chunk.
    // Ente's file decryptors only ever see 4 MiB MESSAGE chunks, and ours
    // rejects anything else (importers' crypto.rs), so this must fail.
    let fs = &v["fileStream"];
    let mut dec = StreamDecryptor::new(&b64(&fs["key"]), &b64(&fs["decryptionHeader"])).unwrap();
    assert!(dec.pull(&b64(&fs["chunks"][0])).is_err());
    let sbx = &v["sealedBox"];
    assert_eq!(
        crypto::box_seal_open(
            &b64(&sbx["sealed"]),
            &b64(&sbx["publicKey"]),
            &b64(&sbx["secretKey"])
        )
        .unwrap(),
        b64(&sbx["plaintext"])
    );
    let a = &v["argon2id"];
    assert_eq!(
        crypto::derive_argon_key(
            a["password"].as_str().unwrap().as_bytes(),
            &b64(&a["salt"]),
            2,
            67_108_864
        )
        .unwrap(),
        b64(&a["key"])
    );
}
